import { Component, EventEmitter, inject, Input, OnInit, Output, SimpleChanges } from '@angular/core';
import { FormularioFlotanteComponent } from "../../../shared/formulario-flotante/formulario-flotante.component";
import { UsuarioService } from '../../../controllers/usuario.service';
import { Usuario } from '../../../models/usuario.model';
import { FormsModule } from '@angular/forms';
import { CurrencyPipe } from '@angular/common';
import { EventoCobroAsignacionService } from '../../../controllers/evento.cobro.asignacion.service';
import { EventoCobroAsignacionUsuarioService } from '../../../controllers/evento.cobro.asignacion.usuario.service';
import { EventoCobroAsignacion } from '../../../models/evento.cobro.asignacion';
import { EventoCobroAsignacionUsuario } from '../../../models/evento.cobro.asignacion.usuario';
import { CobroModalidad } from '../../../models/credito.evento.cobro';
import { UtilsService } from '../../../services/utils.service';

@Component({
  selector: 'app-asignacion-gestiones',
  imports: [
    FormularioFlotanteComponent,
    FormsModule,
    CurrencyPipe,
  ],
  templateUrl: './asignacion-gestiones.component.html',
  styleUrl: './asignacion-gestiones.component.css'
})
export class AsignacionGestionesComponent implements OnInit {
  @Input() show = false;
  @Output() showChange = new EventEmitter<boolean>();
  @Input() selected: Record<string, string>[] = [];

  @Output() done = new EventEmitter<void>()

  public usuarios: Usuario[] = [];
  public selectedUsuarios: Usuario[] = [];
  public fechaAsignacion: string = '';
  public modalidad: CobroModalidad = 'LLAMADA'
  public comentario: string = '';
  // Filtro de búsqueda
  filtroUsuarios: string = '';
  usuariosFiltrados: Usuario[] = [];

  private usuarioController = inject(UsuarioService);
  private utils = inject(UtilsService);
  private eventoCobroAsignacionController = inject(EventoCobroAsignacionService)
  private eventoCobroAsignacionUsuarioController = inject(EventoCobroAsignacionUsuarioService)

  async ngOnInit() {
    await this.setUsuarios();
    this.filtrarUsuarios();
  }

  ngOnChanges(changes: SimpleChanges) {
    if (changes['show'] && this.show) {
      this.refreshData()
    }
  }

  public filtrarUsuarios() {
    const term = this.filtroUsuarios.toLowerCase().trim();
    if (!term) {
      this.usuariosFiltrados = [...this.selectedUsuarios];
    } else {
      this.usuariosFiltrados = this.usuarios.filter(usuario =>
        `${usuario.nombre} ${usuario.apellido_paterno} ${usuario.apellido_materno}`
          .toLowerCase()
          .includes(term)
        || this.selectedUsuarios.find(u => u.id === usuario.id)
      );
    }
  }

  private refreshData() {
    this.fechaAsignacion = new Date().toISOString().substring(0, 10)
    this.comentario = ''
  }

  private async setUsuarios() {
    this.usuarios = await this.usuarioController.usuariosEjecutivosCobranza();
  }

  toggleUsuario(usuario: Usuario) {
    const index = this.selectedUsuarios.findIndex(u => u.id === usuario.id);
    if (index > -1) {
      this.selectedUsuarios.splice(index, 1);
    } else {
      this.selectedUsuarios.push(usuario);
    }
  }

  isSelected(usuario: Usuario): boolean {
    return this.selectedUsuarios.some(u => u.id === usuario.id);
  }

  get totalCreditos(): number {
    return this.selected.length;
  }

  get montoRecuperado(): number {
    return this.selected.reduce((sum, cred) => sum + (parseFloat(cred['MONTO RECUPERADO']) || 0), 0);
  }

  get montoPorRecuperar(): number {
    return this.selected.reduce((sum, cred) => sum + (parseFloat(cred['MONTO POR RECUPERAR']) || 0), 0);
  }

  get promedioMensualidadesVencidas(): number {
    const total = this.selected.reduce((sum, cred) => sum + (parseInt(cred['MENSUALIDADES VENCIDAS']) || 0), 0);
    return this.selected.length ? total / this.selected.length : 0;
  }

  public async aceptar() {
    const now = new Date().toISOString()
    const asignaciones: Partial<EventoCobroAsignacion>[] = this.selected.map(row => ({
      credito_id: +row['ID CREDITO']!,
      fecha: this.fechaAsignacion.substring(0, 10),
      comentarios: this.comentario, modalidad: this.modalidad,
      created_at: this.utils.toMySQLDateTime(now)!,
    }))
    const res = await this.eventoCobroAsignacionController.multipleNews(asignaciones)
    if (!res) return;
    const asignacionesCreadas = await this.eventoCobroAsignacionController.all({
      conditionals: [
        {
          key: 'credito_id',
          operator: 'IN',
          value: this.selected.map(c => +c['ID CREDITO']!).join(',')
        },
        {
          key: 'created_at',
          operator: '=',
          value: this.utils.toMySQLDateTime(now),
        }
      ],
      advancedSearch: [
        {
          relation: 'eventoCobroAsignacionUsuarios',
          conditionals: [],
          andConditionals: [],
          operator: '=',
          count: 0,
        }
      ],
      relations: ['eventoCobroAsignacionUsuarios']
    })
    const asignacionesUsuarios: Partial<EventoCobroAsignacionUsuario>[] = []
    for (const asignacion of asignacionesCreadas) {
      asignacionesUsuarios.push(...this.selectedUsuarios.map(usuario => ({
        evento_cobro_asignacion_id: asignacion.id,
        usuario_asignado_id: usuario.id,
        created_at: this.utils.toMySQLDateTime(now)!
      })))
    }
    const res2 = this.eventoCobroAsignacionUsuarioController.multipleNews(asignacionesUsuarios)
    if (!res2) return;
    this.show = false;
    this.showChange.emit(this.show);
    this.done.emit()
  }
}