import { Component, EventEmitter, inject, Input, Output } from '@angular/core';
import { Conditional, Paginator } from '../../../../controllers/super.service';
import { EventoCobroAsignacion } from '../../../../models/evento.cobro.asignacion';
import { Usuario } from '../../../../models/usuario.model';
import { UtilsService } from '../../../../services/utils.service';
import { EventoCobroAsignacionService } from '../../../../controllers/evento.cobro.asignacion.service';
import { FormsModule } from '@angular/forms';
import { RouterLink } from '@angular/router';
import { AdvancedSearchFilter } from '../../../../shared/tabla/tabla.component';
import { BuscadorCreditosService } from '../../../estado-cuenta/shared/buscador-creditos/buscado.creditos.service';
import { CreditoService } from '../../../../controllers/credito.service';
import { UpperCasePipe } from '@angular/common';

export interface GroupedAssignment {
  date: string;
  comments: string[];
  assignments: (EventoCobroAsignacion & { nombreCliente?: string })[];
  selected: boolean;
  expandend?: boolean;
  showUsers?: boolean;
  stats: {
    total: number;
    completed: number;
    credits: number;
    users: number;
  };
}

@Component({
  selector: 'app-evento-cobro-asignaciones-tabla',
  imports: [
    FormsModule,
    RouterLink,
    UpperCasePipe,
  ],
  templateUrl: './evento-cobro-asignaciones-tabla.component.html',
  styleUrl: './evento-cobro-asignaciones-tabla.component.css'
})
export class EventoCobroAsignacionesTablaComponent {
  @Input() groupedAssignments: GroupedAssignment[] = [];
  @Output() groupedAssignmentsChange = new EventEmitter<GroupedAssignment[]>()

  @Input() selectedAssignments = new Set<number>();
  @Output() selectedAssignmentsChange = new EventEmitter<Set<number>>()

  @Input() canDelete = false
  @Input() canCobrar = false

  @Input() conditionals: Conditional[] = [
    {
      key: 'deleted_at',
      operator: 'IS NULL',
      value: null,
    }
  ]
  @Input() advancedSearch: AdvancedSearchFilter[] = []

  @Input() relations = [
    "eventoCobroAsignacionUsuarios",
    "eventoCobroAsignacionUsuarios.usuarioAsignado",
    "eventoCobroAsignacionUsuarios.creditoEventosCobros",
    "usuarios",
  ];

  @Input() showUserList = false

  paginator: Paginator = { per_page: 500, page: 1 };


  totalItems = 0;
  totalPages = 0;

  eventoCobroAsignacionController = inject(EventoCobroAsignacionService);
  creditoController = inject(CreditoService);
  buscadorCreditos = inject(BuscadorCreditosService)
  municipios = new Map<number, string | undefined>

  public utils = inject(UtilsService)

  async ngOnInit() {
    await this.fetchData();
  }

  async fetchData() {
    this.groupedAssignments = []
    const response = await this.eventoCobroAsignacionController.get({
      conditionals: this.conditionals,
      advancedSearch: this.advancedSearch,
      relations: this.relations,
      paginator: this.paginator,
    });

    this.totalItems = response.total_items ?? 0
    this.totalPages = response.total_pages ?? 0

    this.groupAssignments(response.data || []);
  }

  private async cargarMunicipios(assignments: EventoCobroAsignacion[]) {
    const creditoIds = [...new Set(assignments.map(a => a.credito_id).filter(id => id != null))];

    if (creditoIds.length === 0) return;

    const data = (await this.creditoController.all({
      conditionals: [
        {
          key:'deleted_at',
          operator: 'IS NULL',
          value:null,
        },
        {
          key:'id',
          operator:'IN',
          value: creditoIds.join(','),
        }
      ],
      relations: ['sucursales'],
      columns: ['id', 'sucursal_id'],
      loader:false,
    }))

    data.forEach(c => {
      this.municipios.set(c.id, c.sucursales?.nombre);
    })
  }

  private async precargarNombresClientes(assignments: EventoCobroAsignacion[]) {
    const creditoIds = [...new Set(assignments.map(a => a.credito_id).filter(id => id != null))];

    if (creditoIds.length === 0) return;

    const nombresMap = await this.buscadorCreditos.obtenerCreditosPorIds(creditoIds);

    this.groupedAssignments.forEach(g => g.assignments.forEach(a => {

      a.nombreCliente = nombresMap.get(a.credito_id)
    }))
  }

  public async groupAssignments(assignments: EventoCobroAsignacion[]) {
    const groupsMap = new Map<string, EventoCobroAsignacion[]>();

    assignments.forEach(assignment => {
      // Usar created_at para agrupación en lugar de fecha
      const dateKey = assignment.fecha;
      if (!groupsMap.has(dateKey)) {
        groupsMap.set(dateKey, []);
      }
      groupsMap.get(dateKey)!.push(assignment);
    });

    this.groupedAssignments = Array.from(groupsMap.entries()).map(([dateKey, assignments]) => {
      // Obtener comentarios únicos de esta agrupación
      const uniqueComments = this.getUniqueComments(assignments);

      // Formatear fecha para display usando created_at del primer assignment o fecha como fallback
      const firstAssignment = assignments[0];
      const displayDate = firstAssignment?.fecha
        ? this.utils.fechaFormateada(new Date(firstAssignment.fecha))!
        : firstAssignment?.fecha
          ? this.utils.fechaFormateada(firstAssignment.fecha)!
          : 'Fecha desconocida';

      return {
        date: displayDate,
        comments: uniqueComments,
        assignments,
        selected: false,
        stats: this.calculateStats(assignments)
      };
    })
      .sort((a, b) => {
        // Ordenar por created_at del primer assignment de cada grupo
        const aDate = a.assignments[0]?.created_at ? new Date(a.assignments[0].created_at).getTime() : new Date(a.date).getTime();
        const bDate = b.assignments[0]?.created_at ? new Date(b.assignments[0].created_at).getTime() : new Date(b.date).getTime();
        return bDate - aDate;
      });

    await this.precargarNombresClientes(assignments)
    await this.cargarMunicipios(assignments)
    this.groupedAssignmentsChange.emit(this.groupedAssignments)
  }

  /**
   * Obtiene comentarios únicos de una lista de asignaciones
   */
  private getUniqueComments(assignments: EventoCobroAsignacion[]): string[] {
    const commentsSet = new Set<string>();

    assignments.forEach(assignment => {
      if (assignment.comentarios && assignment.comentarios.trim() !== '') {
        commentsSet.add(assignment.comentarios.trim());
      }
    });

    return Array.from(commentsSet);
  }

  calculateStats(assignments: EventoCobroAsignacion[]) {
    const credits = new Set<number>();
    const users = new Set<number>();
    let completed = 0;

    assignments.forEach(assignment => {
      assignment.evento_cobro_asignacion_usuarios?.forEach(au => {
        credits.add(assignment.credito_id);
        users.add(au.usuario_asignado_id);
      });
      if (assignment.estado === 'COMPLETADA') completed++;
    });

    return {
      total: assignments.length,
      completed,
      credits: credits.size,
      users: users.size
    };
  }

  getCompletedUser(assignment: EventoCobroAsignacion): string {
    const completedUser = assignment.evento_cobro_asignacion_usuarios?.find(
      au => au.usuario_asignado?.id === assignment.usuario_id && au.credito_eventos_cobro_id
    );
    return completedUser?.usuario_asignado?.nombre || 'N/A';
  }

  /**
   * Obtiene la lista de usuarios asignados únicos para un grupo
   */
  getUsuariosAsignados(group: GroupedAssignment): { usuario: Usuario; stats: { total: number; completed: number } }[] {
    const usuariosMap = new Map<number, { usuario: Usuario; stats: { total: number; completed: number } }>();

    group.assignments.forEach(assignment => {
      assignment.evento_cobro_asignacion_usuarios?.forEach(au => {
        if (au.usuario_asignado) {
          const userId = au.usuario_asignado.id;
          const existing = usuariosMap.get(userId);

          if (!existing) {
            usuariosMap.set(userId, {
              usuario: au.usuario_asignado,
              stats: { total: 0, completed: 0 }
            });
          }

          const userStats = usuariosMap.get(userId)!;
          userStats.stats.total++;

          if (assignment.estado === 'COMPLETADA') {
            userStats.stats.completed++;
          }
        }
      });
    });

    return Array.from(usuariosMap.values());
  }

  /**
   * Obtiene las iniciales del nombre de un usuario para el avatar
   */
  getInicialesUsuario(nombre: string): string {
    return nombre
      .split(' ')
      .map(palabra => palabra.charAt(0))
      .join('')
      .toUpperCase()
      .substring(0, 2);
  }

  /**
   * Obtiene el color de fondo para el avatar del usuario basado en su nombre
   */
  getColorAvatar(nombre: string): string {
    const colors = [
      'bg-primary', 'bg-success', 'bg-danger', 'bg-warning',
      'bg-info', 'bg-secondary', 'bg-dark', 'bg-primary-subtle'
    ];

    let hash = 0;
    for (let i = 0; i < nombre.length; i++) {
      hash = nombre.charCodeAt(i) + ((hash << 5) - hash);
    }

    return colors[Math.abs(hash) % colors.length];
  }

  /**
   * Calcula el porcentaje de completado para un usuario
   */
  getPorcentajeCompletado(stats: { total: number; completed: number }): string {
    if (stats.total === 0) return '0.0';
    return ((stats.completed / stats.total) * 100).toFixed(1);
  }

  toggleGroupSelection(group: GroupedAssignment) {
    group.selected = !group.selected;
    group.assignments.forEach(assignment => {
      if (group.selected) {
        this.selectedAssignments.add(assignment.id);
      } else {
        this.selectedAssignments.delete(assignment.id);
      }
      this.selectedAssignmentsChange.emit(this.selectedAssignments)
    });
  }

  toggleSingleSelection(id: number, checked: boolean | null) {
    if (checked) {
      this.selectedAssignments.add(id);
    } else {
      this.selectedAssignments.delete(id);
    }
    this.selectedAssignmentsChange.emit(this.selectedAssignments)
  }

  async deleteSelected() {
    const assignmentsToDelete = Array.from(this.selectedAssignments).map(id => ({
      id,
      deleted_at: this.utils.toMySQLDateTime(new Date())
    }));

    if (await this.eventoCobroAsignacionController.multipleUpdate(assignmentsToDelete)) {
      this.selectedAssignments.clear();
      this.selectedAssignmentsChange.emit(this.selectedAssignments)
      await this.fetchData();
    }
  }

  public async deleteRow(group: GroupedAssignment, asignacion: EventoCobroAsignacion) {
    await this.eventoCobroAsignacionController.switch(asignacion)
    group.assignments = group.assignments.filter(a => !a.deleted_at)
  }

  public asignacionesCompletadas() {
    return this.groupedAssignments.reduce((acc, group) => acc + group.stats.completed, 0)
  }

  public totalSelected(): number {
    return Array.from(this.selectedAssignments).length
  }

  changePage(page: number) {
    if (page < 1 || page > this.totalPages) return;
    this.paginator.page = page;
    this.fetchData();
  }

  get pagesArray(): number[] {
    const pages = [];
    const maxVisiblePages = 5;
    let startPage = Math.max(1, this.paginator.page - Math.floor(maxVisiblePages / 2));
    let endPage = Math.min(this.totalPages, startPage + maxVisiblePages - 1);

    if (endPage - startPage + 1 < maxVisiblePages) {
      startPage = Math.max(1, endPage - maxVisiblePages + 1);
    }

    for (let i = startPage; i <= endPage; i++) {
      pages.push(i);
    }

    return pages;
  }
}
