import { Component } from '@angular/core';
import { Credito } from '../../../models/credito.model';
import { UtilsService } from '../../../services/utils.service';
import { ActivatedRoute } from '@angular/router';
import { CreditoEventoCobroService } from '../../../controllers/credito.evento.cobro.service';
import { CreditoService } from '../../../controllers/credito.service';
import { TablaComponent, TableDefinition } from "../../../shared/tabla/tabla.component";
import { Conditional } from '../../../controllers/super.service';
import { FormCreditoCobroComponent } from "../form-credito-cobro/form-credito-cobro.component";
import { CreditoEventoCobro } from '../../../models/credito.evento.cobro';
import { TABLA_DEF_COBRANZA_EVENTO } from './tabla.eventos.cobranza';
import { TABLA_COBROS_FILTROS_SIMPLES } from './tabla.creditos.cobros.filtros';


@Component({
    selector: 'app-list-credito-cobros',
    imports: [
        TablaComponent,
        FormCreditoCobroComponent
    ],
    templateUrl: './list-credito-cobros.component.html',
    styleUrl: './list-credito-cobros.component.css'
})
export class ListCreditoCobrosComponent {
  tabla= TABLA_DEF_COBRANZA_EVENTO
  filtros= TABLA_COBROS_FILTROS_SIMPLES
  credito?:Credito
  conditionals:Conditional[]=[]
  showForm:boolean=false
  edit?:CreditoEventoCobro

  constructor(
    private utils:UtilsService,
    private route:ActivatedRoute,
    public cobroController: CreditoEventoCobroService,
    private creditoController: CreditoService,
  ){}

  ngOnInit(){
    this.route.paramMap.subscribe(async (params)=>{
      const id= this.utils.intOrNull(params.get('credito_id'))
      if(id){
        this.credito= await this.creditoController.find(id)
        if(this.credito){
          this.conditionals=[{
            key:'credito_id',
            operator:'=',
            value:this.credito.id
          }]
        }
      }
    })
  }

  onEdit(row: CreditoEventoCobro){
    this.edit=row
    this.showForm=true
  }

  onAgregar(){
    this.edit=undefined
    this.showForm=true
  }
}
