@Component({
  selector: 'app-dashboard-cobranza',
  imports: [
    GraphsViewComponent,
    CurrencyPipe,
  ],
  templateUrl: './dashboard-cobranza.component.html',
  styleUrl: './dashboard-cobranza.component.css'
})
export class DashboardCobranzaComponent {
  trendType: "SEMANAL" | 'MENSUAL' = 'SEMANAL'
  // Datos de ejemplo - reemplazar con tus datos reales
  eventoCobroAsignaciones: EventoCobroAsignacion[] = []
  creditosAbonos: { fecha:string; monto:number; }[] = []
  estadosCuenta: Partial<EstadoCuenta>[] =[]


  // Datos importados desde las constantes
  trendData = TREND_DATA_SEMANAL;
  trendDataMensual = TREND_DATA_MENSUAL;
  statusData = STATUS_DATA;
  callResultsData = CALL_RESULTS_DATA;
  performanceData = PERFORMANCE_DATA;
  performanceLabels = PERFORMANCE_LABELS;
  moraData = MORA_DATA;
  amountDistributionData = AMOUNT_DISTRIBUTION_DATA;
  amountDistributionLabels = AMOUNT_DISTRIBUTION_LABELS;

  private eventoCobroAsignacionController = inject(EventoCobroAsignacionService)
  private creditoAbonoController = inject(CreditoAbonoService)
  private estadoCuentaController = inject(EstadoCuentaService)

  async ngOnInit() {
    const today = new Date()
    const fechaFin = today.toISOString().substring(0, 10)
    const fechaInicio = today.getFullYear() + '-' + today.getMonth().toString().padStart(2, '0') + '-' + '01'
    const deleted_conditional = {
      key: 'deleted_at',
      operator: 'IS NULL',
      value: null
    }
    this.eventoCobroAsignaciones = await this.eventoCobroAsignacionController.all({
      relations: [
        "eventoCobroAsignacionUsuarios.creditoEventosCobros",
        "eventoCobroAsignacionUsuarios.usuarioAsignado",
      ],
      conditionals: [
        {
          key: 'fecha',
          operator: '<=',
          value: fechaFin,
        },
        {
          key: 'fecha',
          operator: '>=',
          value: fechaInicio
        },
        deleted_conditional
      ],
      chunkSize: 3000,
    })

    this.creditosAbonos = await this.creditoAbonoController.all({
      columns: ['fecha', 'monto'],
      conditionals: [
        {
          key: 'fecha',
          operator: '<=',
          value: fechaFin,
        },
        {
          key: 'fecha',
          operator: '>=',
          value: fechaInicio
        },
        deleted_conditional
      ]
    })

    this.estadosCuenta = await this.estadoCuentaController.all({
      conditionals:[
        {
          key:'total_a_liquidar',
          operator:'>',
          value:0,
        },
        deleted_conditional
      ],
      columns: ['monto_total_mas_intereses', 'total_a_liquidar']
    })
  }

  get totalAsignados() {
    return this.eventoCobroAsignaciones.length
  }

  get totalGestionados() {
    return this.eventoCobroAsignaciones.filter(a => a.estado == 'COMPLETADA').length
  }

  get diferenciaSemanaAnterior(): number {
    const hoy = new Date();
    const hace7Dias = new Date();
    hace7Dias.setDate(hoy.getDate() - 7);
    const hace14Dias = new Date();
    hace14Dias.setDate(hoy.getDate() - 14);

    // Esta semana (últimos 7 días)
    const asignadosSemanaActual = this.eventoCobroAsignaciones.filter(a => {
      const fechaAsignacion = new Date(a.fecha);
      return fechaAsignacion >= hace7Dias && fechaAsignacion <= hoy;
    });

    // Semana anterior (7 días antes)
    const asignadosSemanaPasada = this.eventoCobroAsignaciones.filter(a => {
      const fechaAsignacion = new Date(a.fecha);
      return fechaAsignacion >= hace14Dias && fechaAsignacion < hace7Dias;
    });

    const cantidadActual = asignadosSemanaActual.length;
    const cantidadPasada = asignadosSemanaPasada.length;

    if (cantidadPasada === 0) {
      return cantidadActual > 0 ? 100 : 0;
    }

    return Math.round(((cantidadActual - cantidadPasada) / cantidadPasada) * 100);
  }

  get gestionadoPorcentaje() {
    if (this.totalAsignados == 0) return 0;
    return (this.totalGestionados / this.totalAsignados) * 100
  }

  get efectividad(): number {
    if (this.totalGestionados === 0) return 0;

    // Considerando que "efectivos" son los gestionados con estado positivo
    // Ajusta esta lógica según tu definición de efectividad
    const efectivos = this.eventoCobroAsignaciones.filter(a =>
      a.estado === 'COMPLETADA' && this.esGestionEfectiva(a)
    ).length;

    return Math.round((efectivos / this.totalGestionados) * 100);
  }

  // Función auxiliar para determinar si una gestión fue efectiva
  private esGestionEfectiva(asignacion: EventoCobroAsignacion): boolean {
    const gestion = asignacion.evento_cobro_asignacion_usuarios?.find(a => a.credito_eventos_cobros)?.credito_eventos_cobros
    if (!gestion) return false;
    return gestion.resultado === 'PROMESA DE PAGO' ||
      gestion.resultado === 'LOCALIZADO' ||
      gestion.resultado === "LIQUIDADO" ||
      gestion.resultado.includes('CONVENIO')
  }

  get diferenciaEfectividadMesAnterior(): number {
    const hoy = new Date();
    const inicioMesActual = new Date(hoy.getFullYear(), hoy.getMonth(), 1);
    const inicioMesAnterior = new Date(hoy.getFullYear(), hoy.getMonth() - 1, 1);
    const finMesAnterior = new Date(hoy.getFullYear(), hoy.getMonth(), 0);

    // Efectividad del mes actual
    const gestionadosMesActual = this.eventoCobroAsignaciones.filter(a => {
      const fechaAsignacion = new Date(a.fecha);
      return fechaAsignacion >= inicioMesActual &&
        fechaAsignacion <= hoy &&
        a.estado === 'COMPLETADA';
    });

    const efectivosMesActual = gestionadosMesActual.filter(a =>
      this.esGestionEfectiva(a)
    ).length;

    const efectividadActual = gestionadosMesActual.length > 0
      ? (efectivosMesActual / gestionadosMesActual.length) * 100
      : 0;

    // Efectividad del mes anterior
    const gestionadosMesAnterior = this.eventoCobroAsignaciones.filter(a => {
      const fechaAsignacion = new Date(a.fecha);
      return fechaAsignacion >= inicioMesAnterior &&
        fechaAsignacion <= finMesAnterior &&
        a.estado === 'COMPLETADA';
    });

    const efectivosMesAnterior = gestionadosMesAnterior.filter(a =>
      this.esGestionEfectiva(a)
    ).length;

    const efectividadAnterior = gestionadosMesAnterior.length > 0
      ? (efectivosMesAnterior / gestionadosMesAnterior.length) * 100
      : 0;

    if (efectividadAnterior === 0) {
      return efectividadActual > 0 ? 100 : 0;
    }

    return Math.round(((efectividadActual - efectividadAnterior) / efectividadAnterior) * 100);
  }

  // Propiedad formateada para mostrar en el template
  get diferenciaEfectividadFormateada(): string {
    const diferencia = this.diferenciaEfectividadMesAnterior;
    if (diferencia > 0) {
      return `+${diferencia}%`;
    } else if (diferencia < 0) {
      return `${diferencia}%`;
    } else {
      return '0%';
    }
  }

  get montoRecuperadoTotal(){
    return this.creditosAbonos.reduce((acc,a) => acc+ +a.monto,0)
  }

  get porcentajeRecuperado(){
    if(this.totalCartera ==0) return 0;
    return  (this.montoRecuperadoTotal/this.totalCartera)*100
  }

  get totalCartera(){
    return this.estadosCuenta.reduce((acc,e) => acc+ +(e.monto_total_mas_intereses??0),0)
  }

  get totalPendiente(){
    return this.estadosCuenta.reduce((acc,e) => acc+ +(e.total_a_liquidar??0),0)
  }
}
