import { Component, EventEmitter, Input, Output, SimpleChanges } from '@angular/core';
import { FormularioFlotanteComponent } from '../../../shared/formulario-flotante/formulario-flotante.component';
import { Credito } from '../../../models/credito.model';
import { CreditoEventoCobro } from '../../../models/credito.evento.cobro';

import { Router, RouterLink } from '@angular/router';
import { AutocompleteFieldComponent } from "../../../shared/generic-form/autocomplete-field/autocomplete-field.component";
import { FormsModule } from '@angular/forms';
import { UtilsService } from '../../../services/utils.service';
import { CreditoEventoCobroService } from '../../../controllers/credito.evento.cobro.service';
import { LocalStorageService } from '../../../services/localStorage/local-storage.service';

@Component({
    selector: 'app-form-credito-cobro',
    imports: [
    FormularioFlotanteComponent,
    RouterLink,
    AutocompleteFieldComponent,
    FormsModule
],
    templateUrl: './form-credito-cobro.component.html',
    styleUrl: './form-credito-cobro.component.css'
})
export class FormCreditoCobroComponent {
  @Input() show:boolean=false
  @Output() showChange = new EventEmitter<boolean>()

  @Input() credito?:Credito
  @Input() cobroEvento?: CreditoEventoCobro
  @Output() saved = new EventEmitter<boolean>()
  asignarUsuario:'SI'|'NO'='NO'
  nuevoCobro:CreditoEventoCobro={
    credito_id: 0,
    usuario_ejecutivo_id: 0,
    modalidad: 'LLAMADA',
    resultado: 'OTRO',
    comentario: '',
    usuario_id: 0,
    id: 0,
    fecha: (new Date()).toISOString().substring(0,10),
    deleted_at: null,
    created_at: '',
    updated_at: null
  }

  constructor(
    public utils: UtilsService,
    private eventoCobroController: CreditoEventoCobroService,
    private storage: LocalStorageService,
    private router: Router,
  ){}

  ngOnChanges(changes:SimpleChanges){
    if(changes['show'] && this.show){
      this.nuevoCobro={
        credito_id: 0,
        usuario_ejecutivo_id: 0,
        modalidad: 'LLAMADA',
        resultado: 'OTRO',
        comentario: '',
        usuario_id: 0,
        id: 0,
        fecha: (new Date()).toISOString().substring(0,10),
        deleted_at: null,
        created_at: '',
        updated_at: null
      }
    }
    if(changes['cobroEvento'] && this.cobroEvento){
      this.nuevoCobro= this.cobroEvento
      this.nuevoCobro.fecha= this.cobroEvento.fecha?.substring(0,10)??null
    }
  }

  async submit(){
    if(!this.credito) return
    this.nuevoCobro.credito_id=this.credito.id
    if(this.asignarUsuario==='NO'){
      this.nuevoCobro.usuario_ejecutivo_id=this.storage.getUser().id
    }
    const res= await this.eventoCobroController.createOrUpdate(this.nuevoCobro)
    console.log(res)
    if(res && this.asignarUsuario==='NO'){
      this.router.navigate(['/main/cobranza/ejecucion',res.id])
      return
    }
    this.saved.emit(true)
  }
}
