import { Component, inject } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { contratoNotificaciones } from '../../../services/documentosLegales/contratos/contrato_notificaciones.service';
import { COBRANZA_COLUMNS_CLUSTERS, InformeCobranzaService } from '../../informes/services/informe-cobranza.service';
import { ConsolidadoRow, FilterOptions } from '../../informes/services/consolidado.super.service';
import { ProgressBarConsolidadoComponent } from "../../informes/shared/progress-bar-consolidado/progress-bar-consolidado.component";
import { InformeTablaDinamicaLocalComponent } from "../../informes/informe-tabla-dinamica-local/informe-tabla-dinamica-local.component";
import { Credito } from '../../../models/credito.model';
import { DatesPickerComponent } from "../../informes/shared/dates-picker/dates-picker.component";
import { FormularioFlotanteComponent } from '../../../shared/formulario-flotante/formulario-flotante.component';

@Component({
    selector: 'app-notificaciones',
    imports: [
    FormsModule,
    ProgressBarConsolidadoComponent,
    InformeTablaDinamicaLocalComponent,
    DatesPickerComponent,
    FormularioFlotanteComponent
],
    templateUrl: './notificaciones.component.html',
    styleUrl: './notificaciones.component.css'
})
export class NotificacionesComponent {
  creditos:Credito[]=[]
  dataSource: ConsolidadoRow[] = []
  columnsClusters = COBRANZA_COLUMNS_CLUSTERS
  progress = 0
  isLoading = false
  showForm=false
  options:FilterOptions={}

  selected:ConsolidadoRow[]=[]

  showFolioForm = false
  folioInicial: number = 0
  fechaNotificacion: string = ''

  private informeCobranzaController = inject(InformeCobranzaService)
  private notificacion = inject(contratoNotificaciones)

  async ngOnInit() {
    this.informeCobranzaController.progress$.subscribe(p => {
      this.progress = p
    })
  }

  public async fetchData(){
    this.isLoading=true
    this.dataSource = await this.informeCobranzaController.fetchDataMaped(this.options)
    this.creditos = await this.informeCobranzaController.fetchData(this.options)
    console.log(this.creditos)
    this.isLoading=false
  }

  public imprimirNotificaciones(){
    if (this.selected.length === 0) return
    this.folioInicial=0
    this.fechaNotificacion=''
    this.showFolioForm = true
  }

  public async generarNotificacionesConFolios() {
    const selected = this.selected.map(r => r['ID CREDITO'] as number)
    const creditos = this.creditos.filter(c => selected.includes(c.id))

    if (creditos.length === 0 || !this.folioInicial || !this.fechaNotificacion) {
      return
    }

    const folios = creditos.map((_, index) => ({
      folio: this.folioInicial + index,
      fecha: this.fechaNotificacion
    }))

    await this.notificacion.generarNotificacion(creditos, folios)
    this.showFolioForm = false
  }

  public cerrarFormularioFolio() {
    this.showFolioForm = false
    this.folioInicial = 0
    this.fechaNotificacion = ''
  }
}
