import { Component, inject } from '@angular/core';
import { AdvancedSearchFilter } from "../../../shared/tabla/tabla.component";
import { Conditional } from '../../../controllers/super.service';
import { LocalStorageService } from '../../../services/localStorage/local-storage.service';
import { UsuarioLogin } from '../../../auth/auth.model';
import { GroupedAssignment, EventoCobroAsignacionesTablaComponent } from '../shared/evento-cobro-asignaciones-tabla/evento-cobro-asignaciones-tabla.component';
import { UtilsService } from '../../../services/utils.service';

@Component({
  selector: 'app-list-cobros-asignados',
  imports: [
    EventoCobroAsignacionesTablaComponent
],
  templateUrl: './list-cobros-asignados.component.html',
  styleUrl: './list-cobros-asignados.component.css'
})
export class ListCobrosAsignadosComponent {
  advancedSearch: AdvancedSearchFilter[] = []
  usuario: UsuarioLogin
  relations = [
    'usuarioAsignado',
    'eventoCobroAsignacion.eventoCobroAsignacionUsuarios.usuarios',
  ]
  groupedAssignments: GroupedAssignment[] = [];
  selectedAssignments = new Set<number>();

  public utils = inject(UtilsService)
  private localStorage = inject(LocalStorageService)


  constructor() {
    this.usuario = this.localStorage.getUser()

    this.advancedSearch= [
    {
      relation: 'eventoCobroAsignacionUsuarios',
      conditionals: [
        ['usuario_asignado_id', '=', this.usuario.id]
      ],
      andConditionals: [],
    }
  ]
  }
  public asignacionesCompletadas() {
    return this.groupedAssignments.reduce((acc, group) => acc + group.stats.completed, 0)
  }

  get totalGestiones(){
    return this.groupedAssignments.flatMap(a => a.assignments).length
  }
}