import { Component, inject, ViewChild, OnChanges, SimpleChanges } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { EventoCobroAsignacionService } from '../../../controllers/evento.cobro.asignacion.service';
import { UtilsService } from '../../../services/utils.service';
import { GroupedAssignment, EventoCobroAsignacionesTablaComponent } from '../shared/evento-cobro-asignaciones-tabla/evento-cobro-asignaciones-tabla.component';
import { CreditoService } from '../../../controllers/credito.service';
import { Conditional } from '../../../controllers/super.service';

@Component({
  selector: 'app-list-cobros-asignaciones',
  imports: [
    FormsModule,
    EventoCobroAsignacionesTablaComponent,
  ],
  templateUrl: './list-cobros-asignaciones.component.html',
})
export class ListCobrosAsignacionesComponent {
  @ViewChild(EventoCobroAsignacionesTablaComponent) tabla !: EventoCobroAsignacionesTablaComponent
  groupedAssignments: GroupedAssignment[] = [];
  selectedAssignments = new Set<number>();
  estadisticasPorMunicipio: { municipio: string; count: number }[] = [];

  eventoCobroAsignacionController = inject(EventoCobroAsignacionService);
  public utils = inject(UtilsService);
  private creditoService = inject(CreditoService);

  public asignacionesCompletadas() {
    return this.groupedAssignments.reduce((acc, group) => acc + group.stats.completed, 0)
  }

  get totalGestiones() {
    return this.groupedAssignments.flatMap(a => a.assignments).length
  }

  get estadisticasPorMunicipioConPorcentaje() {
    const total = this.groupedAssignments.flatMap(g => g.assignments).filter(g => g.estado == 'EN PROGRESO').length;
    return this.estadisticasPorMunicipio.map(item => ({
      ...item,
      porcentaje: total > 0 ? ((item.count / total) * 100).toFixed(1) : '0.0'
    }));
  }

  async cargarEstadisticasPorMunicipio() {
    // Paso 1: Obtener todos los credito_id de TODAS las asignaciones (incluyendo duplicados)
    const allCreditoIds = this.groupedAssignments
      .flatMap(group => group.assignments.map(assignment => assignment.credito_id))
      .filter(id => id != null); // Filtrar nulos

    if (allCreditoIds.length === 0) {
      this.estadisticasPorMunicipio = [];
      return;
    }

    // Paso 2: Obtener créditos únicos (para no repetir peticiones)
    const uniqueCreditoIds = [...new Set(allCreditoIds)];

    // Paso 3: Consultar créditos con sus sucursales
    const conditionals: Conditional[] = [{
      key: 'id',
      operator: 'IN',
      value: uniqueCreditoIds.join(',')
    }];

    const creditos = await this.creditoService.all({
      conditionals,
      relations: ['sucursales'],
      loader: false,
      columns: ['id', 'sucursal_id']
    });

    // Paso 4: Crear mapa rápido: credito_id → municipio
    const creditoToMunicipio = new Map<number, string>();
    creditos.forEach(credito => {
      const municipio = credito.sucursales?.nombre?.toUpperCase() || 'SIN MUNICIPIO';
      creditoToMunicipio.set(credito.id, municipio);
    });

    // Paso 5: Contar asignaciones por municipio (¡incluyendo duplicados!)
    const municipioCount = {} as { [municipio: string]: number };

    allCreditoIds.forEach(creditoId => {
      const municipio = creditoToMunicipio.get(creditoId) || 'SIN MUNICIPIO';
      municipioCount[municipio] = (municipioCount[municipio] || 0) + 1;
    });

    // Paso 6: Ordenar y asignar
    this.estadisticasPorMunicipio = Object.entries(municipioCount)
      .sort(([, a], [, b]) => b - a) // descendente
      .map(([municipio, count]) => ({
        municipio,
        count: count as number
      }));
  }

  get totalMunicipios() {
    return Object.keys(this.estadisticasPorMunicipio).length;
  }
}